// features/lifecycle.feature: "A vendor cannot be renamed to another vendor's name, whatever the case"
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("renaming a vendor to another vendor's name in a different case is rejected", { tag: "@LIF-10" }, async ({ apiAs, factory }) => {
    // Arrange
    const taken = await factory.vendor({ as: "member", name: uniqueName("Atlas Freight") });
    const borealis = await factory.vendor({ as: "member", name: uniqueName("Borealis Freight") });
    const member = await apiAs("member");
    const shoutedName = taken.name.toUpperCase();

    // Act
    const response = await member.patch(`/api/vendors/${borealis.id}`, {
      data: { name: shoutedName },
    });

    // Assert
    const body = await expectStatus<{ error: { code: string } }>(response, 409);
    expect(body.error.code).toBe("vendor_name_taken");

    const stored = await expectStatus<{ name: string }>(await member.get(`/api/vendors/${borealis.id}`), 200);
    expect(stored.name).toBe(borealis.name);
  });
});
